import { MeshStandardNodeMaterial } from 'three/webgpu';
import {
  uv,
  vec2,
  vec3,
  float,
  abs,
  max,
  length,
  smoothstep,
  mix,
  texture,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, DoubleSide } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const group = new Group();
  group.name = 'hub-collection-badge';

  // --- capsule dimensions (small badge, atlas rect 512x320 -> aspect ~1.6) ---
  const width = 0.9;
  const height = 0.32;
  const aspect = width / height;

  const geometry = new PlaneGeometry(width, height, 1, 1);

  // --- TSL capsule SDF ---
  const p = uv().sub(0.5).mul(vec2(aspect, 1.0));
  const halfLength = float((1.0 - height / width) * 0.5 * aspect);
  const radius = float(0.5);
  const qx = max(abs(p.x).sub(halfLength), float(0.0));
  const dist = length(vec2(qx, p.y)).sub(radius);

  const edgeWidth = float(0.015);
  const shapeMask = smoothstep(edgeWidth, float(0.0), dist); // 1 inside, 0 outside
  const edgeBand = smoothstep(edgeWidth.mul(4.0), float(0.0), abs(dist)); // thin ring near border

  const surfaceColor = vec3(
    parseInt(colors.surface.slice(1, 3), 16) / 255,
    parseInt(colors.surface.slice(3, 5), 16) / 255,
    parseInt(colors.surface.slice(5, 7), 16) / 255
  );
  const inkColor = vec3(
    parseInt(colors.ink.slice(1, 3), 16) / 255,
    parseInt(colors.ink.slice(3, 5), 16) / 255,
    parseInt(colors.ink.slice(5, 7), 16) / 255
  );
  const accentColor = vec3(
    parseInt(colors.accent.slice(1, 3), 16) / 255,
    parseInt(colors.accent.slice(3, 5), 16) / 255,
    parseInt(colors.accent.slice(5, 7), 16) / 255
  );

  const material = new MeshStandardNodeMaterial({
    transparent: true,
    side: DoubleSide,
    roughness: 0.55,
    metalness: 0.35,
  });

  // base body color: surface toward center, ink toward inner edge
  const bodyColor = mix(surfaceColor, inkColor, smoothstep(float(-0.18), float(0.0), dist));
  material.colorNode = bodyColor;
  material.emissiveNode = accentColor.mul(edgeBand).mul(1.4);
  material.opacityNode = shapeMask;

  const mesh = new Mesh(geometry, material);
  mesh.position.set(0, 0, 0);
  group.add(mesh);

  // grain texture overlay
  let grainTex = null;
  const imageUrl = config.imageUrl;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      grainTex = tex;
      const grain = texture(tex, uv());
      material.colorNode = mix(bodyColor, bodyColor.mul(grain.r.mul(0.3).add(0.85)), float(0.6));
      material.needsUpdate = true;
    }).catch(() => {});
  }

  // apply configured cinematic primitives (none specified, but honor contract)
  const primitiveHandles = [];
  const primitives = Array.isArray(config.cinematicPrimitives) ? config.cinematicPrimitives : [];
  for (const prim of primitives) {
    const fn = ctx.primitives?.[prim.name];
    if (typeof fn === 'function') {
      const handle = fn(group, prim.params ?? {});
      if (handle) primitiveHandles.push(handle);
    }
  }

  // --- interactions ---
  const baseY = 0;
  const baseScale = 1;
  let hoverTl = null;
  let pressTl = null;

  const handlers = {};

  handlers.pointerover = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(group.position, {
      y: baseY + 0.15,
      duration: 0.5,
      ease: 'power3.out',
    }, 0);
    hoverTl.to(group.scale, {
      x: baseScale * 1.03,
      y: baseScale * 1.03,
      z: baseScale * 1.03,
      duration: 0.5,
      ease: 'power3.out',
    }, 0);
  };

  handlers.pointerout = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(group.position, {
      y: baseY,
      duration: 0.5,
      ease: 'power2.out',
    }, 0);
    hoverTl.to(group.scale, {
      x: baseScale,
      y: baseScale,
      z: baseScale,
      duration: 0.5,
      ease: 'power2.out',
    }, 0);
  };

  handlers.pointerdown = () => {
    if (pressTl) pressTl.kill();
    pressTl = gsap.timeline();
    pressTl.to(group.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out(2)',
    });
  };

  handlers.pointerup = () => {
    if (pressTl) pressTl.kill();
    pressTl = gsap.timeline();
    pressTl.to(group.scale, {
      x: 1.0,
      y: 1.0,
      z: 1.0,
      duration: 0.9,
      ease: 'power4.out',
    });
  };

  handlers.click = () => {
    ctx.emit('hub-collection.select', { source: 'hub-collection-badge' });
  };

  group.userData.handlers = handlers;

  group.userData.cleanup = () => {
    if (hoverTl) hoverTl.kill();
    if (pressTl) pressTl.kill();
    for (const h of primitiveHandles) {
      try {
        h.timeline?.kill();
        h.cleanup?.();
      } catch (e) {
        // noop
      }
    }
    geometry.dispose();
    material.dispose();
    if (grainTex) grainTex.dispose?.();
  };

  return group;
}
